import sys, time, random
sys.path.insert(0,'/workspace/submission')
from compiler import Job, find_deficient_cut, compile_plan, check_plan

def a100(nn, gpus=8, nv=30, ib=3):
    links=[]; idx={}
    def node(x):
        if x not in idx:
            idx[x]=len(idx); links.append(None)
        return idx[x]
    gsw=[]
    for a in range(nn):
        sw = node(('sw',a))
        for b in range(gpus):
            g = node(('g',a,b))
            links[g] = (g, sw, nv)
        gsw.append(sw)
    if nn>1:
        for j in range(2):
            ibx = node(('ib',j))
            for a in range(nn):
                for b in range(gpus):
                    g = node(('g',a,b))
                    if (min(g,ibx),max(g,ibx)) in seen: pass
        # add NIC paths: gpu -> ib (b%2)
    return links, idx

def fabric(nn, gpus=4, nv=30, ibn=3):
    """GPUs 0..N-1, one NVSwitch per node, two IB switches."""
    N = nn*gpus
    links=[]
    sw = [N+i for i in range(nn)]
    ib = [N+nn, N+nn+1]
    seen=set()
    def add(u,v,c):
        k=(min(u,v),max(u,v))
        if k in seen: return
        seen.add(k)
        links.append((u,v,c))
    for a in range(nn):
        for b in range(gpus):
            g=a*gpus+b
            add(g, sw[a], nv)
    if nn>1:
        for a in range(nn):
            for b in range(gpus):
                g=a*gpus+b
                add(g, ib[b%2], ibn)
    n = N+nn+2
    return n, links

rng=random.Random(4)
for (nn, gpus, nv, ibn, rate_nv, rate_ib, dem) in [
    (2,4,30,3,4,2,10),
    (3,4,30,3,6,2,5),
    (4,8,30,25,10,4,20),
    (2,4,30,3,1,1,4),
    (3,4,8,3,3,1,7),
]:
    n, links = fabric(nn, gpus, nv, ibn)
    m=len(links)
    gpulist=list(range(nn*gpus))
    ps = rng.sample(gpulist, min(len(gpulist), rng.randint(3, 10)))
    demands={v: (dem if rng.random()<0.7 else 0) for v in ps}
    if sum(demands.values())==0: demands[ps[0]]=dem
    env={}
    for l,(u,v,c) in enumerate(links):
        # offered envelope: NVLink links get rate_nv, IB links get rate_ib
        if v >= nn*gpus and v < nn*gpus+nn:
            env[l]=rate_nv
        else:
            env[l]=rate_ib
    job=Job(n, links, demands, 1, env)
    t0=time.monotonic(); cut=find_deficient_cut(job); tc=time.monotonic()-t0
    if cut is not None:
        print(f'fabric nn={nn} gpus={gpus} rn={rate_nv} ri={rate_ib} dem={dem}: DENIED cut size {len(cut)}')
        continue
    t0=time.monotonic(); plan=compile_plan(job, budget=25); dt=time.monotonic()-t0
    ok = plan is not None and check_plan(job, plan)
    print(f'fabric nn={nn} gpus={gpus} rn={rate_nv} ri={rate_ib} dem={dem} |C|={len(ps)}: ok={ok} time={dt:.2f} trees={len(plan["trees"]) if plan else "-"} routes={len(plan["routes"]) if plan else "-"} recipes={len(plan["recipes"]) if plan else "-"}')
